import json, re, urllib.request, sys

BASE = "http://localhost:3000/api"
TOKEN = open("/tmp/edupsych_token").read().strip()
PATIENT_ID = "cmsezw1em000f8882p6561p4b"  # Theo Mendes Rocha
PROF_ID = "cmsezw1dr00028882hv5std1k"     # Ana Carolina Silva (PROFISSIONAL)
TODAY = "2026-08-17"

def parse_protocol(path):
    src = open(path).read()
    domains = {}
    for m in re.finditer(r"id: '([a-z_0-9]+)',\s*code: '([^']*)',\s*name: '([^']+)',\s*color: '([^']*)'", src):
        did = m.group(1)
        items = []
        for im in re.finditer(r"\{\s*id: '(%s\d+)'" % did[:2], src):
            items.append(im.group(1))
        domains[did] = {"name": m.group(3), "items": items}
    return domains

def generate_scores(domains, max_score, factor):
    evals = {}
    for did, d in domains.items():
        for i, item in enumerate(d["items"]):
            score = max_score * factor * max(0.0, 1 - 0.07 * i)
            evals[item] = min(max_score, max(0, round(score)))
    return evals

def api(method, path, body=None):
    req = urllib.request.Request(BASE + path, method=method)
    req.add_header("Authorization", f"Bearer {TOKEN}")
    req.add_header("Content-Type", "application/json")
    data = json.dumps(body).encode() if body is not None else None
    try:
        with urllib.request.urlopen(req, data) as r:
            return r.status, json.loads(r.read() or b"null")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()[:300]

protocols = [
    ("ablls-r", "src/app/modules/protocolos-aba/data/ablls-r.ts", 2, 0.85, "Avaliação ABLLS-R inicial: repertório de conduta básica consolidado; linguagem receptiva superior à expressiva; habilidades acadêmicas em fase inicial."),
    ("vb-mapp", "src/app/modules/protocolos-aba/data/vb-mapp.ts", 3, 0.65, "VB-MAPP: mand e listener com bons repertórios iniciais; habilidades sociais e linguagem receptiva avançada (LRFFC) ainda em aquisição."),
    ("denver", "src/app/modules/protocolos-aba/data/denver.ts", 3, 0.75, "ESDM: motor grosso e fino com marcos consolidados; linguagem e interação social em desenvolvimento com suporte."),
]

existing = {a["protocolType"]: a["id"] for a in api("GET", "/aba/assessments")[1]["data"]}

for proto, path, maxs, factor, notes in protocols:
    domains = parse_protocol(path)
    evals = generate_scores(domains, maxs, factor)
    total = sum(evals.values())
    domain_scores = {did: sum(evals[i] for i in d["items"]) for did, d in domains.items()}
    body = {
        "patientId": PATIENT_ID,
        "professionalId": PROF_ID,
        "protocolType": proto.upper(),
        "evaluations": json.dumps(evals),
        "totalScore": total,
        "domainScores": json.dumps(domain_scores),
        "notes": notes,
        "assessedAt": TODAY,
    }
    if proto.upper() in existing:
        status, resp = api("PUT", f"/aba/assessments/{existing[proto.upper()]}", body)
        action = f"ATUALIZADO ({existing[proto.upper()]})"
    else:
        status, resp = api("POST", "/aba/assessments", body)
        action = f"CRIADO ({resp.get('id', '?')})"
    print(f"[{status}] {proto.upper()}: {action} | itens={len(evals)} total={total} domínios={len(domain_scores)}")

#!/usr/bin/env python3
import json, re, urllib.request

BASE = "http://localhost:3000/api"
TOKEN = open("/tmp/edupsych_token").read().strip()
PATIENT_ID = "cmsezw1em000f8882p6561p4b"  # Theo Mendes Rocha
PROF_ID = "cmsezw1dr00028882hv5std1k"     # Ana Carolina Silva (PROFISSIONAL)
TODAY = "2026-08-17"

def parse_protocol(path):
    src = open(path).read()
    domains = {}
    pat = re.compile(
        r"\{\s*id: '([^']+)',\s*code: '[^']*',\s*name: '([^']+)',\s*color: '[^']*',\s*(?:skills|milestones|items): \[(.*?)\]\s*\}",
        re.S,
    )
    for m in pat.finditer(src):
        did, name, block = m.group(1), m.group(2), m.group(3)
        items = re.findall(r"id: '([^']+)'", block)
        domains[did] = {"name": name, "items": items}
    return domains

def generate_scores(domains, max_score, factor):
    evals = {}
    for did, d in domains.items():
        for i, item in enumerate(d["items"]):
            score = max_score * factor * max(0.0, 1 - 0.07 * i)
            evals[item] = min(max_score, max(0, round(score)))
    return evals

def api(method, path, body=None):
    req = urllib.request.Request(BASE + path, method=method)
    req.add_header("Authorization", f"Bearer {TOKEN}")
    req.add_header("Content-Type", "application/json")
    data = json.dumps(body).encode() if body is not None else None
    try:
        with urllib.request.urlopen(req, data) as r:
            return r.status, json.loads(r.read() or b"null")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()[:300]

status, resp = api("GET", f"/aba/assessments?patientId={PATIENT_ID}")
existing = {a["protocolType"]: a["id"] for a in resp["data"]}
print("avaliações existentes do Theo:", existing)

protocols = [
    ("ABLLS-R", "src/app/modules/protocolos-aba/data/ablls-r.ts", 2, 0.85, "Avaliação ABLLS-R inicial: conduta básica e habilidades motoras consolidadas; linguagem receptiva superior à expressiva; habilidades acadêmicas em fase inicial de aquisição."),
    ("VB-MAPP", "src/app/modules/protocolos-aba/data/vb-mapp.ts", 3, 0.65, "VB-MAPP: mand, listener e echoic com repertórios iniciais consistentes; tato em expansão; habilidades sociais e LRFFC ainda em aquisição."),
    ("DENVER", "src/app/modules/protocolos-aba/data/denver.ts", 3, 0.75, "ESDM: motor grosso e fino com marcos consolidados; linguagem receptiva em desenvolvimento; interação social com suporte do terapeuta."),
]

for proto, path, maxs, factor, notes in protocols:
    domains = parse_protocol(path)
    evals = generate_scores(domains, maxs, factor)
    total = sum(evals.values())
    domain_scores = {did: sum(evals[i] for i in d["items"]) for did, d in domains.items()}
    body = {
        "patientId": PATIENT_ID,
        "professionalId": PROF_ID,
        "protocolType": proto,
        "evaluations": json.dumps(evals),
        "totalScore": total,
        "domainScores": json.dumps(domain_scores),
        "notes": notes,
        "assessedAt": TODAY,
    }
    if proto in existing:
        status, resp = api("PUT", f"/aba/assessments/{existing[proto]}", body)
        action = f"ATUALIZADO {existing[proto]}"
    else:
        status, resp = api("POST", "/aba/assessments", body)
        action = f"CRIADO {resp.get('id', '?') if isinstance(resp, dict) else resp}"
    print(f"[{status}] {proto}: {action} | itens={len(evals)} total={total} | resposta: {str(resp)[:120]}")

