#!/usr/bin/env python3
import json, re, urllib.request

BASE = "http://localhost:3000/api"
TOKEN = open("/tmp/edupsych_token").read().strip()
PATIENT_ID = "cmsezw1em000f8882p6561p4b"  # Theo Mendes Rocha
PROF_ANA = "cmsezw1dr00028882hv5std1k"    # Ana Carolina Silva
PROF_CARLOS = "cmsezw1du00038882y8j151yr" # Carlos Eduardo Santos

def parse_protocol(path):
    src = open(path).read()
    domains = {}
    pat = re.compile(
        r"\{\s*id: '([^']+)',\s*code: '[^']*',\s*name: '([^']+)',\s*color: '[^']*',\s*(?:skills|milestones|items): \[(.*?)\]\s*\}",
        re.S,
    )
    for m in pat.finditer(src):
        did, name, block = m.group(1), m.group(2), m.group(3)
        items = re.findall(r"id: '([^']+)'", block)
        domains[did] = {"name": name, "items": items}
    return domains

def generate_scores(domains, max_score, factor):
    evals = {}
    for did, d in domains.items():
        for i, item in enumerate(d["items"]):
            base = max_score * factor * max(0.0, 1 - 0.07 * i)
            jitter = (sum(ord(c) for c in item) % 3) - 1
            evals[item] = min(max_score, max(0, round(base + jitter)))
    return evals

def api(method, path, body=None):
    req = urllib.request.Request(BASE + path, method=method)
    req.add_header("Authorization", f"Bearer {TOKEN}")
    req.add_header("Content-Type", "application/json")
    data = json.dumps(body).encode() if body is not None else None
    try:
        with urllib.request.urlopen(req, data) as r:
            return r.status, json.loads(r.read() or b"null")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()[:200]

status, resp = api("GET", f"/aba/assessments?patientId={PATIENT_ID}")
existing = {a["protocolType"]: a for a in resp["data"]}
print("avaliações existentes do Theo:", {k: v["assessedAt"][:10] for k, v in existing.items()})

ROUNDS = [
    # (data, fator, profissional, sufixo de notas)
    ("2026-08-10", 0.45, PROF_CARLOS, "Linha de base inicial"),
    ("2026-08-17", 0.65, PROF_ANA, "Reavaliação após 1 semana"),
]

protocols = [
    ("ABLLS-R", "src/app/modules/protocolos-aba/data/ablls-r.ts", 2, "Condução da avaliação de habilidades de linguagem e aprendizado."),
    ("VB-MAPP", "src/app/modules/protocolos-aba/data/vb-mapp.ts", 3, "Avaliação de marcos de linguagem e comportamento verbal."),
    ("DENVER", "src/app/modules/protocolos-aba/data/denver.ts", 3, "Avaliação de marcos de desenvolvimento pela abordagem ESDM."),
]

created = []
for proto, path, maxs, base_note in protocols:
    domains = parse_protocol(path)
    for date, factor, prof, round_label in ROUNDS:
        evals = generate_scores(domains, maxs, factor)
        total = sum(evals.values())
        domain_scores = {did: sum(evals[i] for i in d["items"]) for did, d in domains.items()}
        body = {
            "patientId": PATIENT_ID,
            "professionalId": prof,
            "protocolType": proto,
            "evaluations": json.dumps(evals),
            "totalScore": total,
            "domainScores": json.dumps(domain_scores),
            "notes": f"{round_label} — {base_note}",
            "assessedAt": date + "T12:00:00.000Z",
        }
        # Se já existe avaliação com MESMA data e protocolo → PUT; senão POST
        match = next((a for a in existing.values() if a["protocolType"] == proto and a["assessedAt"][:10] == date), None)
        if match:
            status, r = api("PUT", f"/aba/assessments/{match['id']}", body)
            action = f"ATUALIZADO {match['id'][:12]}"
        else:
            status, r = api("POST", "/aba/assessments", body)
            action = f"CRIADO {r.get('id','?')[:12] if isinstance(r, dict) else r}"
        created.append((proto, date, total, status))
        print(f"[{status}] {proto} ({date}): {action} | itens={len(evals)} total={total}")

print("\nResumo:")
for proto, date, total, status in created:
    print(f"  {proto} {date}: {total} pts [{status}]")

