      pacienteId: this.form.pacienteId,
      sessionNumber: 1,
      date: new Date().toISOString().split('T')[0],
      professionalName: '',
      objective: '',
      instruments: '',
      studentBehavior: '',
      activities: '',
      observations: ''
    };
  }

