              <span class="material-icons text-[28px]"
                [class]="dangerMode ? 'text-red-500' : 'text-amber-500'">
                {{ dangerMode ? 'delete_forever' : 'warning' }}
              </span>
            </div>
            <h3 class="text-lg font-bold text-slate-900 dark:text-white mb-2">{{ title }}</h3>
